import React, { useMemo, useState } from 'react';
import {
  Popover,
  Box,
  Typography,
  Avatar,
  ListItemButton,
  ListItemIcon,
  ListItemText,
  useMediaQuery,
  Chip,
} from '@mui/material';
import PasswordIcon from '@mui/icons-material/Password';
import ChangePassword from '../../page/User/component/ChangePassword';
import CallSplitIcon from '@mui/icons-material/CallSplit';
import LogoutIcon from '@mui/icons-material/Logout';
import BranchChange from './BranchChange';
import { useGetAllBranchQuery, useGetUserQuery } from '../../page/posApi';
import { IBranchDetails } from '../../core/Interface/branch.interface';
import { useTranslation } from 'react-i18next';
import { useTheme } from '@mui/material/styles';
import { appColors, brandColors, HEADER_GRADIENT } from '../../theme/appColors';
import { IUserInfo } from '../../core/Interface/user.interface';

interface ProfilePopupProps {
  profile: HTMLElement | null;
  onClose: () => void;
  open: boolean;
  Username: string | boolean;
  Branchname: string | boolean;
}

const ProfilePopup: React.FC<ProfilePopupProps> = ({
  profile,
  onClose,
  open,
  Username,
  Branchname,
}) => {
  const id = open ? 'simple-popover' : undefined;
  const [openPassword, setOpenPassword] = React.useState(false);
  const [openBranchChange, setOpenBranchChange] = useState(false);
  const { t } = useTranslation(['branchManage', 'common']);

  const { data } = useGetUserQuery();
  const branchName = useMemo(() => {
    if (data?.data) {
      const userData = data.data as IUserInfo;
      return userData.branch.name;
    }
    return '';
  }, [data]);

  const userImageUrl = useMemo(() => {
    if (data?.data) {
      const userData = data.data as IUserInfo;
      return userData.imageUrl;
    }
    return '';
  }, [data]);

  const logout = () => {
    localStorage.removeItem('token');
    window.location.reload();
  };

  const handleTokenChange = () => {
    window.location.reload();
  };

  const { data: branchCountData } = useGetAllBranchQuery({
    pageIndex: 0,
    pageSize: 50,
    searchText: '',
  });

  const branchList = useMemo(() => {
    return branchCountData?.data as IBranchDetails;
  }, [branchCountData?.data]);

  const showChangeBranchOption = branchList?.records.length > 1;
  const theme = useTheme();
  const isSmall = useMediaQuery(theme.breakpoints.down('sm'));

  const avatarSize = isSmall ? 52 : 64;
  const initials = typeof Username === 'string'
    ? Username.slice(0, 2).toUpperCase()
    : 'U';

  return (
    <Popover
      PaperProps={{
        sx: {
          borderRadius: 3,
          overflow: 'hidden',
          width: 280,
          boxShadow: '0 8px 32px rgba(15,29,77,0.18)',
        },
      }}
      anchorEl={profile}
      anchorOrigin={{ vertical: 'bottom', horizontal: 'center' }}
      id={id}
      keepMounted
      onClose={onClose}
      open={open}
      transformOrigin={{ vertical: 'top', horizontal: 'center' }}
    >
      {/* Gradient Header */}
      <Box
        sx={{
          background: HEADER_GRADIENT,
          pt: 3,
          pb: 2.5,
          px: 2,
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          gap: 1,
        }}
      >
        {/* Avatar with ring */}
        <Box
          sx={{
            width: avatarSize + 8,
            height: avatarSize + 8,
            borderRadius: '50%',
            background: 'rgba(255,255,255,0.25)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            mb: 0.5,
          }}
        >
          <Avatar
            alt={typeof Username === 'string' ? Username : 'User'}
            src={userImageUrl || undefined}
            sx={{
              width: avatarSize,
              height: avatarSize,
              fontSize: avatarSize * 0.36,
              fontWeight: 700,
              backgroundColor: brandColors.teal,
              color: '#fff',
              border: '2px solid rgba(255,255,255,0.8)',
            }}
          >
            {!userImageUrl && initials}
          </Avatar>
        </Box>

        {/* Username */}
        <Typography
          sx={{
            color: '#fff',
            fontWeight: 700,
            fontSize: '1rem',
            letterSpacing: 0.3,
            lineHeight: 1.2,
          }}
          variant="subtitle1"
        >
          {Username}
        </Typography>

        {/* Branch chip */}
        <Chip
          label={Branchname}
          size="small"
          sx={{
            backgroundColor: 'rgba(255,255,255,0.18)',
            color: 'rgba(255,255,255,0.9)',
            fontSize: '0.72rem',
            fontWeight: 600,
            height: 22,
            border: '1px solid rgba(255,255,255,0.3)',
            '& .MuiChip-label': { px: 1.2 },
          }}
        />
      </Box>

      {/* Menu Items */}
      <Box sx={{ py: 1, backgroundColor: '#fff' }}>
        {showChangeBranchOption && (
          <ListItemButton
            onClick={() => setOpenBranchChange(true)}
            sx={{
              mx: 1,
              borderRadius: 1.5,
              py: 1,
              mb: 0.25,
              '&:hover': { backgroundColor: `${appColors.amberYellow[100]}12` },
            }}
          >
            <ListItemIcon sx={{ minWidth: 36 }}>
              <Box
                sx={{
                  width: 30,
                  height: 30,
                  borderRadius: 1,
                  backgroundColor: `${appColors.amberYellow[100]}18`,
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                }}
              >
                <CallSplitIcon sx={{ fontSize: 17, color: appColors.amberYellow[100] }} />
              </Box>
            </ListItemIcon>
            <ListItemText
              primary={t('branchManage:switch')}
              primaryTypographyProps={{ fontSize: '0.875rem', fontWeight: 500, color: '#374151' }}
            />
          </ListItemButton>
        )}

        <ListItemButton
          onClick={() => setOpenPassword(true)}
          sx={{
            mx: 1,
            borderRadius: 1.5,
            py: 1,
            mb: 0.25,
            '&:hover': { backgroundColor: `${brandColors.teal}12` },
          }}
        >
          <ListItemIcon sx={{ minWidth: 36 }}>
            <Box
              sx={{
                width: 30,
                height: 30,
                borderRadius: 1,
                backgroundColor: `${brandColors.teal}18`,
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
              }}
            >
              <PasswordIcon sx={{ fontSize: 17, color: brandColors.teal }} />
            </Box>
          </ListItemIcon>
          <ListItemText
            primary={t('branchManage:changePassword')}
            primaryTypographyProps={{ fontSize: '0.875rem', fontWeight: 500, color: '#374151' }}
          />
        </ListItemButton>

        {/* Separator */}
        <Box sx={{ mx: 2, my: 0.75, height: 1, backgroundColor: '#f3f4f6' }} />

        <ListItemButton
          onClick={logout}
          sx={{
            mx: 1,
            borderRadius: 1.5,
            py: 1,
            '&:hover': { backgroundColor: `${appColors.carmineRed[100]}10` },
          }}
        >
          <ListItemIcon sx={{ minWidth: 36 }}>
            <Box
              sx={{
                width: 30,
                height: 30,
                borderRadius: 1,
                backgroundColor: `${appColors.carmineRed[100]}15`,
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
              }}
            >
              <LogoutIcon sx={{ fontSize: 17, color: appColors.carmineRed[100] }} />
            </Box>
          </ListItemIcon>
          <ListItemText
            primary={t('branchManage:logout')}
            primaryTypographyProps={{ fontSize: '0.875rem', fontWeight: 600, color: appColors.carmineRed[100] }}
          />
        </ListItemButton>
      </Box>

      {/* Footer */}
      <Box
        sx={{
          backgroundColor: '#f9fafb',
          borderTop: '1px solid #f3f4f6',
          py: 1,
          px: 2,
          textAlign: 'center',
        }}
      >
        <Typography sx={{ fontSize: '0.7rem', color: '#9ca3af' }}>
          Nexshora POS Management Portal
        </Typography>
      </Box>

      {openPassword && (
        <ChangePassword
          handleCloseDialog={() => setOpenPassword(false)}
          openModel={openPassword}
          title="Change Password"
        />
      )}
      {openBranchChange && (
        <BranchChange
          handleCloseDialog={() => setOpenBranchChange(false)}
          onTokenChange={handleTokenChange}
          openModel={openBranchChange}
          selectedBranch={branchName}
          title="Change Branch"
        />
      )}
    </Popover>
  );
};

export default ProfilePopup;
