import React, { useEffect, useState } from 'react';
import {
  Box,
  Button,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Grid,
  Stack,
  TextField,
  Typography,
} from '@mui/material';
import ScaleOutlinedIcon from '@mui/icons-material/ScaleOutlined';
import { useTranslation } from 'react-i18next';
import { useSelector } from 'react-redux';
import { selectBasketItems } from '../../../store/SalesRichBasketSelector';
import FieldHeader from '../../../../../components/FieldHeader';
import { HEADER_GRADIENT } from '../../../../../theme/appColors';

interface IKgPopup {
  open: boolean;
  handleCloseAlert: () => void;
  unitPrice: number;
  handleAdd: (calculatedValue: number | null, inputCount: number) => void;
  productId: string;
}

const inputSx = {
  '& .MuiOutlinedInput-root': {
    borderRadius: '8px',
    '&.Mui-focused fieldset': { borderColor: '#0F8B8D' },
  },
  '& label.Mui-focused': { color: '#0F8B8D' },
};

const KgPopup: React.FC<IKgPopup> = ({
  open,
  handleCloseAlert,
  unitPrice,
  handleAdd,
  productId,
}) => {
  const { t } = useTranslation(['common']);
  const [amount, setAmount] = useState<string>('');
  const [calculatedValue, setCalculatedValue] = useState<number | null>(null);
  const selectItem = useSelector(selectBasketItems);
  const selectedItem = selectItem.find((item) => item.id === productId);

  useEffect(() => {
    if (selectedItem) {
      const count = selectedItem.count ?? 0;
      const calculated = count * selectedItem.unitPrice;
      setAmount(count ? count.toString() : '');
      setCalculatedValue(!isNaN(calculated) ? calculated : 0);
    }
  }, [selectedItem]);

  const handleAmountChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const inputCount = event.target.value;
    setAmount(inputCount);
    const calculated = parseFloat(inputCount) * unitPrice;
    setCalculatedValue(calculated);
  };

  const handleAddClick = () => {
    if (calculatedValue !== null) {
      handleAdd(calculatedValue, parseFloat(amount));
      handleCloseAlert();
    }
  };

  return (
    <Dialog
      onClose={handleCloseAlert}
      open={open}
      PaperProps={{
        sx: {
          borderRadius: '12px',
          overflow: 'hidden',
          width: 400,
          maxWidth: 'calc(100vw - 32px)',
        },
      }}
    >
      <DialogTitle sx={{ p: 0 }}>
        <Box sx={{ background: HEADER_GRADIENT, px: 3, py: 2 }}>
          <Stack alignItems="center" direction="row" spacing={1.5}>
            <Box
              sx={{
                alignItems: 'center',
                background: 'rgba(255,255,255,0.15)',
                borderRadius: '8px',
                display: 'flex',
                height: 36,
                justifyContent: 'center',
                width: 36,
                flexShrink: 0,
              }}
            >
              <ScaleOutlinedIcon sx={{ color: '#fff', fontSize: 20 }} />
            </Box>
            <Box>
              <Typography sx={{ color: '#fff', fontSize: '1rem', fontWeight: 800, lineHeight: 1.2 }}>
                Enter Weight or Liters
              </Typography>
              <Typography sx={{ color: 'rgba(255,255,255,0.7)', fontSize: '0.72rem', fontWeight: 500 }}>
                Calculate amount by quantity
              </Typography>
            </Box>
          </Stack>
        </Box>
      </DialogTitle>

      <DialogContent sx={{ px: 3, pt: 2.5, pb: 1 }}>
        <Grid container spacing={2}>
          <Grid item xs={12}>
            <FieldHeader title="Weight or Liters" />
            <TextField
              autoComplete="off"
              autoFocus
              fullWidth
              onChange={handleAmountChange}
              placeholder="Enter Kg/L (1kg 500g = 1.5)"
              size="small"
              sx={inputSx}
              type="number"
              inputProps={{ step: 'any' }}
              value={amount}
              variant="outlined"
            />
          </Grid>
          <Grid item xs={12}>
            <FieldHeader title="Amount" />
            <Box
              sx={{
                alignItems: 'center',
                background: 'rgba(15,139,141,0.07)',
                border: '1px solid rgba(15,139,141,0.2)',
                borderRadius: '8px',
                display: 'flex',
                height: 40,
                justifyContent: 'flex-end',
                px: 1.5,
              }}
            >
              <Typography sx={{ color: '#0F8B8D', fontSize: '1rem', fontWeight: 800 }}>
                {calculatedValue !== null && !isNaN(calculatedValue)
                  ? calculatedValue.toFixed(2)
                  : '—'}
              </Typography>
            </Box>
          </Grid>
        </Grid>
      </DialogContent>

      <DialogActions sx={{ borderTop: '1px solid #E2E8F0', gap: 1.5, px: 3, py: 2 }}>
        <Button
          onClick={handleCloseAlert}
          sx={{
            borderColor: '#CBD5E1',
            borderRadius: '8px',
            color: '#475569',
            fontWeight: 600,
            height: 40,
            minWidth: 110,
            px: 3,
            textTransform: 'none',
            '&:hover': { background: '#F1F5F9', borderColor: '#94A3B8' },
          }}
          variant="outlined"
        >
          {t('common:cancel')}
        </Button>
        <Button
          onClick={handleAddClick}
          sx={{
            background: HEADER_GRADIENT,
            borderRadius: '8px',
            boxShadow: '0 4px 14px rgba(15,29,77,0.25)',
            color: '#fff',
            fontWeight: 700,
            height: 40,
            minWidth: 110,
            px: 3,
            textTransform: 'none',
            '&:hover': { opacity: 0.9 },
          }}
          variant="contained"
        >
          Add
        </Button>
      </DialogActions>
    </Dialog>
  );
};

export default KgPopup;
