import { Box, Grid, Paper, Stack, styled, Typography } from '@mui/material';
import React, { useEffect, useRef, useState } from 'react';
import { appColors } from '../../../../theme/appColors';
import LockIcon from '@mui/icons-material/Lock';
import DeleteIcon from '@mui/icons-material/Delete';
import PointOfSaleIcon from '@mui/icons-material/PointOfSale';
import PaymentMethodsModel from './Model/PaymentMethodsModel';
import { PaymentType } from '../../../../core/types/commonType';
import {
  addCustomerDetailes,
  clearCustomer,
  clearSaleId,
  removeBasket,
} from '../../store/SalesRichBasketSlice';
import AttachMoneyIcon from '@mui/icons-material/AttachMoney';
import {
  useSaveVoidBulkItemFromBasketMutation,
  useGetSalesDetailsByOrderIdQuery,
  useGetUserQuery,
  useGetLastSaleQuery,
} from '../../../posApi';
import BackdropLoading from '../../../../components/BackdropLoading';
import { useAppSelector, useAppDispatch } from '../../../../store/hooks';
import { useNotifier } from '../../../../core/Notifier';
import { useReactToPrint } from 'react-to-print';
import { PrintReceipt } from './components/PrintReceipt';
import { IUserInfo } from '../../../../core/Interface/user.interface';
import { calculateFontSize } from '../../../../core/utils';
import PrintIcon from '@mui/icons-material/Print';
import ConfirmationModel from '../../../../components/ModelPopup/ConfirmationModel';
import { useTranslation } from 'react-i18next';
import WhatsAppIcon from '@mui/icons-material/WhatsApp';
import PayCreditPopup from '../../../Customer/component/PayPopup';
import { ICustomerDetailsData } from '../../../../core/Interface/customer.interface';
import { IAddCustomer } from '../../../../core/Interface/property.interface';
import { ISaleRichReceipt } from '../../../../core/Interface/saleRich.interface';

const Item = styled(Paper)(({ theme }) => ({
  ...theme.typography.body2,
  textAlign: 'center',
  verticalAlign: 'middle',
  height: 'var(--tile-h)',
  display: 'flex',
  justifyContent: 'center',
  alignItems: 'center',
  borderRadius: '10px',
  cursor: 'pointer',
}));

const btnLabel = (text: string, color = '#0F1D4D') => (
  <Typography sx={{ fontWeight: 700, fontSize: 11, color, mt: '2px' }}>{text}</Typography>
);

const LastSection = () => {
  const { t } = useTranslation(['salesRich', 'customer']);
  const dispatch = useAppDispatch();
  const [openPaymentMethod, setOpenPaymentMethod] = React.useState(false);
  const [pt, setPt] = useState('');
  const { showErrorMessage, showMessage } = useNotifier();
  const basket = useAppSelector((state) => state.salesRichBasket);
  const hasCustomer = Boolean(basket.customerId && basket.mobile);
  const [isDeleting, setIsDeleting] = useState(false);
  const [openDeleteConfirmation, setOpenDeleteConfirmation] = useState(false);
  const [openPayCreditPopup, setOpenPayCreditPopup] = React.useState(false);
  // eslint-disable-next-line max-len
  const [customerData, setCustomerData] = React.useState<ICustomerDetailsData | undefined>();
  const saleId = useAppSelector((state) => state.salesRichBasket.saleId);
  const isPendingSale = Boolean(saleId);
  const basketItems = useAppSelector((state) => state.salesRichBasket.items);
  const hasItems = basketItems.length > 0;
  const receiptRef = useRef<HTMLDivElement>(null);
  const [isPrinting, setIsPrinting] = useState(false);
  const [lastReceipt, setLastReceipt] = useState<ISaleRichReceipt | null>(null);
  const [fetchLastSale, setFetchLastSale] = useState(false);
  const [actionType, setActionType] = useState<'print' | 'whatsapp' | null>(null);
  // eslint-disable-next-line max-len
  const [pendingSaleIdToPrint, setPendingSaleIdToPrint] = useState<string | null>(null);
  const [requestPendingPrint, setRequestPendingPrint] = useState(false);
  // eslint-disable-next-line max-len
  const [pendingReceipt, setPendingReceipt] = useState<ISaleRichReceipt | null>(null);

  const { data: companyData } = useGetUserQuery();
  // eslint-disable-next-line max-len
  const [saveVoidItemFromBasket, { isLoading }] = useSaveVoidBulkItemFromBasketMutation();
  // eslint-disable-next-line max-len
  const { data: lastSaleResponse, isLoading: isLoadingLastSale } = useGetLastSaleQuery(undefined, { skip: !fetchLastSale });
  // eslint-disable-next-line max-len
  const { data: pendingReceiptResponse, isLoading: isLoadingPendingSale } = useGetSalesDetailsByOrderIdQuery(
    pendingSaleIdToPrint as string,
    { skip: !pendingSaleIdToPrint || !requestPendingPrint }
  );

  const hasHandledPendingPrintRef = useRef(false);

  const printPaperSizeInPixel = React.useMemo(() => {
    if (companyData?.data) {
      const userData = companyData.data as IUserInfo;
      // eslint-disable-next-line max-len
      if (userData.branch.printPaperSizeInPixel) return Number(userData.branch.printPaperSizeInPixel);
    }
    return 10;
  }, [companyData]);

  const handlePrint = useReactToPrint({
    content: () => receiptRef.current,
    onBeforePrint: () => setIsPrinting(true),
    onAfterPrint: () => setIsPrinting(false),
  });

  const handleLastSale = () => { setActionType('print'); setFetchLastSale(true); };
  const handleWhatsAppSend = () => { setActionType('whatsapp'); setFetchLastSale(true); };

  useEffect(() => {
    if (!fetchLastSale || !lastSaleResponse?.data || !actionType) return;
    const lastSale = lastSaleResponse.data as ISaleRichReceipt;
    if (actionType === 'print') { setLastReceipt(lastSale); setTimeout(() => handlePrint(), 50); }
    if (actionType === 'whatsapp') {
      if (!lastSale.whatsAppShareLink) { showErrorMessage(t('salesRich:noMobileNumberEntered')); }
      else {
        const webLink = lastSale.whatsAppShareLink.replace('whatsapp://send', 'https://wa.me/');
        window.open(webLink, '_blank');
        showMessage(t('salesRich:whatsAppMessageOpenedSuccessfully'));
        setTimeout(() => showMessage(''), 200);
      }
    }
    setFetchLastSale(false);
    setActionType(null);
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [fetchLastSale, lastSaleResponse, actionType, handlePrint]);

  const handlePendingSale = (id: string) => {
    hasHandledPendingPrintRef.current = false;
    setPendingSaleIdToPrint(id);
    setRequestPendingPrint(true);
    setPendingReceipt(null);
  };

  useEffect(() => {
    if (requestPendingPrint && pendingReceiptResponse?.data) {
      setPendingReceipt(pendingReceiptResponse.data as ISaleRichReceipt);
    }
  }, [requestPendingPrint, pendingReceiptResponse]);

  useEffect(() => {
    // eslint-disable-next-line max-len
    if (pendingReceipt && requestPendingPrint && !hasHandledPendingPrintRef.current) {
      hasHandledPendingPrintRef.current = true;
      handlePrint();
      setRequestPendingPrint(false);
      setPendingReceipt(null);
      setPendingSaleIdToPrint(null);
    }
  // eslint-disable-next-line max-len
  }, [pendingReceipt, requestPendingPrint, handlePrint, dispatch]);

  // eslint-disable-next-line max-len
  const paySales = async () => { setPt(PaymentType.CACHE); setOpenPaymentMethod(true); };

  const handleDeleteAll = async () => {
    if (!basketItems.length || isDeleting) return;
    setIsDeleting(true);
    // eslint-disable-next-line max-len
    const payload = basketItems.map((item: { id: string; count: number }) => ({ productId: item.id, qty: item.count }));
    try {
      const response = await saveVoidItemFromBasket(payload).unwrap();
      if (!response.status) { showErrorMessage(response.message); return; }
      showMessage(response.message);
      setTimeout(() => showMessage(''), 2000);
      dispatch(removeBasket());
      dispatch(clearSaleId());
      dispatch(clearCustomer());
      setOpenDeleteConfirmation(false);
    } catch (error) {
      showErrorMessage((error as Error).message);
    } finally { setIsDeleting(false); }
  };

  const handlePayCredit = (CustomerDetails: ICustomerDetailsData) => {
    setCustomerData(CustomerDetails);
    setOpenPayCreditPopup(true);
  };

  const handlePayCreditClose = (updatedCustomerData?: ICustomerDetailsData) => {
    setOpenPayCreditPopup(false);
    if (!updatedCustomerData) return;
    // eslint-disable-next-line max-len
    const updatedCustomer: IAddCustomer = { ...updatedCustomerData, id: String(updatedCustomerData.id) };
    dispatch(addCustomerDetailes(updatedCustomer));
  };

  return (
    <Box>
      <Grid
        container
        spacing={1}
      >
        {/* Lock */}
        <Grid
          item
          key="last-05"
          md={1.5}
          sm={1.5}
          xs={4}
        >
          <Item
            onClick={hasItems ? () => {} : undefined}
            sx={{
              background: 'linear-gradient(135deg, #fef3c7 0%, #fde68a 100%)',
              opacity: hasItems ? 1 : 0.35,
              cursor: hasItems ? 'pointer' : 'default',
            }}
          >
            <Stack
              alignItems="center"
              direction="column"
            >
              <LockIcon sx={{ fontSize: 26, color: '#d97706' }} />
              {btnLabel('Hold')}
            </Stack>
          </Item>
        </Grid>

        {/* Delete */}
        <Grid
          item
          key="last-06"
          md={1.5}
          sm={1.5}
          xs={4}
        >
          <Item
            // eslint-disable-next-line max-len
            onClick={hasItems ? () => setOpenDeleteConfirmation(true) : undefined}
            sx={{
              background: 'linear-gradient(135deg, #fee2e2 0%, #fecaca 100%)',
              opacity: hasItems ? 1 : 0.35,
              cursor: hasItems ? 'pointer' : 'default',
            }}
          >
            <Stack
              alignItems="center"
              direction="column"
            >
              <DeleteIcon sx={{ fontSize: 26, color: '#DC2626' }} />
              {btnLabel('Delete')}
            </Stack>
          </Item>
        </Grid>

        {/* Pay Credit */}
        <Grid
          item
          key="last-01"
          md={1.5}
          sm={1.5}
          xs={4}
        >
          <Item
            onClick={
              hasCustomer
                ? () => handlePayCredit({ customerId: basket.customerId ?? '', mobile: basket.mobile, name: basket.customerName } as ICustomerDetailsData)
                : undefined
            }
            sx={{
              background: 'linear-gradient(135deg, #f3e8ff 0%, #e9d5ff 100%)',
              opacity: hasCustomer ? 1 : 0.35,
              cursor: hasCustomer ? 'pointer' : 'default',
            }}
          >
            <Stack
              alignItems="center"
              direction="column"
            >
              <AttachMoneyIcon sx={{ fontSize: 26, color: '#7c3aed' }} />
              {btnLabel('Pay Credit')}
            </Stack>
          </Item>
        </Grid>

        {/* WhatsApp Latest Sale */}
        <Grid
          item
          key="last-02"
          md={1.5}
          sm={1.5}
          xs={4}
        >
          <Item
            onClick={handleWhatsAppSend}
            sx={{
              background: 'linear-gradient(135deg, #dcfce7 0%, #bbf7d0 100%)',
            }}
          >
            <Stack
              alignItems="center"
              direction="column"
            >
              <WhatsAppIcon sx={{ fontSize: 26, color: '#16a34a' }} />
              {btnLabel('WhatsApp')}
            </Stack>
          </Item>
        </Grid>

        {/* Print Latest Sale */}
        <Grid
          item
          key="last-03"
          md={1.5}
          sm={1.5}
          xs={4}
        >
          <Item
            // eslint-disable-next-line max-len
            onClick={isPrinting || isLoadingLastSale ? undefined : handleLastSale}
            sx={{
              background: 'linear-gradient(135deg, #fef3c7 0%, #fde68a 100%)',
              cursor: 'pointer',
              pointerEvents: isPrinting || isLoadingLastSale ? 'none' : 'auto',
            }}
          >
            <Stack
              alignItems="center"
              direction="column"
            >
              <PrintIcon sx={{ fontSize: 26, color: '#d97706' }} />
              {btnLabel('Last Print')}
            </Stack>
          </Item>
        </Grid>

        {/* Print Order */}
        <Grid
          item
          key="last-04"
          md={1.5}
          sm={1.5}
          xs={4}
        >
          <Item
            // eslint-disable-next-line max-len
            onClick={isPendingSale ? () => handlePendingSale(saleId!) : undefined}
            sx={{
              background: 'linear-gradient(135deg, #dbeafe 0%, #bfdbfe 100%)',
              opacity: isPendingSale ? 1 : 0.3,
              cursor: isPendingSale ? 'pointer' : 'default',
            }}
          >
            <Stack
              alignItems="center"
              direction="column"
            >
              <PrintIcon sx={{ fontSize: 26, color: '#1d4ed8' }} />
              {btnLabel('Order', '#1e3a8a')}
            </Stack>
          </Item>
        </Grid>

        {/* PAY — prominent */}
        <Grid
          item
          key="last-07"
          md={3}
          sm={3}
          xs={4}
        >
          <Item
            onClick={hasItems ? paySales : undefined}
            sx={{
              background: hasItems
                ? 'linear-gradient(135deg, #0F8B8D 0%, #0F1D4D 100%)'
                : 'rgba(148,163,184,0.25)',
              opacity: hasItems ? 1 : 0.35,
              cursor: hasItems ? 'pointer' : 'default',
              boxShadow: hasItems ? '0 4px 14px rgba(15,139,141,0.35)' : 'none',
            }}
          >
            <Stack
              alignItems="center"
              direction="row"
              spacing={1}
            >
              <PointOfSaleIcon sx={{ fontSize: 32, color: appColors.white }} />
              <Typography sx={{ fontWeight: 900, fontSize: 20, color: appColors.white, letterSpacing: '0.5px' }}>
                PAY
              </Typography>
            </Stack>
          </Item>
        </Grid>
      </Grid>

      <PaymentMethodsModel
        handleClose={() => setOpenPaymentMethod(false)}
        open={openPaymentMethod}
        paymentType={pt}
      />

      {(lastReceipt || pendingReceipt) && (
        <Box sx={{ display: 'none' }}>
          <PrintReceipt
            fontSize={calculateFontSize(printPaperSizeInPixel).fontSize}
            fontWeight={calculateFontSize(printPaperSizeInPixel).fontWeight}
            label={calculateFontSize(printPaperSizeInPixel).label}
            ref={receiptRef}
            salesRes={pendingReceipt ?? lastReceipt!}
            width={printPaperSizeInPixel}
          />
        </Box>
      )}

      {openDeleteConfirmation && (
        <ConfirmationModel
          content={t('salesRich:confirmDeleteMessage')}
          handleClose={() => setOpenDeleteConfirmation(false)}
          isProcessing={isDeleting}
          onConfirm={() => handleDeleteAll()}
          open={openDeleteConfirmation}
          title={t('salesRich:confirmDeleteTitle')}
        />
      )}

      {openPayCreditPopup && (
        <PayCreditPopup
          data={customerData}
          // eslint-disable-next-line max-len
          handleCloseDialog={(close: boolean) => handlePayCreditClose(customerData)}
          openModel={openPayCreditPopup}
          title={t('customer:amount')}
        />
      )}

      {/* eslint-disable-next-line max-len */}
      <BackdropLoading isLoading={isLoading || isLoadingLastSale || isLoadingPendingSale} />
    </Box>
  );
};

export default React.memo(LastSection);
