import {
  Box,
  Button,
  Checkbox,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  FormControlLabel,
  InputAdornment,
  Slide,
  Stack,
  TextField,
  Typography,
} from '@mui/material';
import { alpha } from '@mui/material/styles';
import React from 'react';
import { TransitionProps } from '@mui/material/transitions';
import { appColors } from '../../../../../theme/appColors';
import {
  addDiscount,
} from '../../../store/SalesRichBasketSlice';
import { useAppDispatch } from '../../../../../store/hooks';
import { useFormik } from 'formik';
import { IDiscount } from '../../../../../core/Interface/property.interface';
import { useSelector } from 'react-redux';
import { selectDiscount } from '../../../store/SalesRichBasketSelector';
import LocalOfferOutlinedIcon from '@mui/icons-material/LocalOfferOutlined';

interface IDiscountModel {
  title?: string;
  open: boolean;
  handleClose: () => void;
}

const inputFieldSx = {
  '& .MuiOutlinedInput-root': {
    backgroundColor: alpha(appColors.white, 0.92),
    borderRadius: '4px',
    '& fieldset': { borderColor: alpha(appColors.blueGreyishLight[80], 0.16) },
    '&:hover fieldset': { borderColor: alpha('#2563EB', 0.28) },
    '&.Mui-focused': { boxShadow: `0 0 0 4px ${alpha('#2563EB', 0.10)}` },
    '&.Mui-focused fieldset': { borderColor: '#2563EB' },
  },
};

const labelSx = {
  color: '#142352',
  fontSize: '0.86rem',
  fontWeight: 700,
  mb: 0.8,
};

const Transition = React.forwardRef(function Transition(
  props: TransitionProps & { children: React.ReactElement<string, string> },
  ref: React.Ref<unknown>
) {
  return (
    <Slide
      direction="up"
      ref={ref}
      {...props}
    />
  );
});

// eslint-disable-next-line react/no-multi-comp
const DiscountModel: React.FC<IDiscountModel> = ({
  title,
  open,
  handleClose,
}) => {
  const dispatch = useAppDispatch();
  const selectDis = useSelector(selectDiscount);

  const formik = useFormik({
    initialValues: {
      discount: selectDis.discount,
      discountAsPercentage: selectDis.discountAsPercentage,
    },
    enableReinitialize: true,
    onSubmit: (values) => {
      const disData: IDiscount = values;
      dispatch(addDiscount(disData));
      handleClose();
    },
    validate: () => ({}),
  });

  return (
    <Dialog
      PaperProps={{
        component: 'form',
        noValidate: true,
        onSubmit: formik.handleSubmit,
        sx: {
          background: 'linear-gradient(180deg, rgba(255,255,255,0.98) 0%, rgba(248,251,255,0.96) 100%)',
          border: `1px solid ${alpha(appColors.blueGreyishLight[80], 0.1)}`,
          borderRadius: '8px',
          boxShadow: '0 30px 80px rgba(15,23,42,0.28)',
          maxWidth: 'calc(100vw - 32px)',
          overflow: 'hidden',
          width: 560,
        },
      }}
      TransitionComponent={Transition}
      fullWidth
      maxWidth="xs"
      onClose={handleClose}
      open={open}
    >
      {/* Header */}
      <DialogTitle sx={{ p: 0 }}>
        <Box
          sx={{
            background: `linear-gradient(135deg, ${alpha('#2563EB', 0.06)} 0%, ${alpha(appColors.blueGreyishLight[80], 0.04)} 100%)`,
            borderBottom: `1px solid ${alpha(appColors.blueGreyishLight[80], 0.12)}`,
            px: 3,
            py: 2,
          }}
        >
          <Stack
            alignItems="center"
            direction="row"
            spacing={1.5}
          >
            <Box
              sx={{
                alignItems: 'center',
                background: `linear-gradient(135deg, #2563EB 0%, #1d4ed8 100%)`,
                borderRadius: '8px',
                color: appColors.white,
                display: 'flex',
                height: 36,
                justifyContent: 'center',
                width: 36,
              }}
            >
              <LocalOfferOutlinedIcon sx={{ fontSize: 18 }} />
            </Box>
            <Box>
              <Typography
                sx={{ color: '#142352', fontSize: '1rem', fontWeight: 800, lineHeight: 1.2 }}
              >
                {title ?? 'Apply Discount'}
              </Typography>
              <Typography
                sx={{ color: alpha('#142352', 0.5), fontSize: '0.75rem', fontWeight: 500 }}
              >
                Set invoice-level discount
              </Typography>
            </Box>
          </Stack>
        </Box>
      </DialogTitle>

      {/* Body */}
      <DialogContent sx={{ p: 0 }}>
        <Box sx={{ px: 3, py: 3 }}>
          <Typography sx={labelSx}>Discount Value</Typography>
          <TextField
            InputProps={{
              endAdornment: formik.values.discountAsPercentage
                ? (
                  <InputAdornment position="end">
                    <Typography
                      sx={{
                        color: alpha(appColors.blueGreyishLight[80], 0.72),
                        fontSize: 13,
                        fontWeight: 600,
                      }}
                    >
                      %
                    </Typography>
                  </InputAdornment>
                )
                : undefined,
              inputProps: { min: 0 },
            }}
            autoComplete="off"
            fullWidth
            placeholder="0.00"
            size="small"
            sx={inputFieldSx}
            type="number"
            inputProps={{ step: 'any' }}
            {...formik.getFieldProps('discount')}
          />

          <Box sx={{ mt: 2 }}>
            <FormControlLabel
              control={
                <Checkbox
                  checked={formik.values.discountAsPercentage}
                  name="discountAsPercentage"
                  onChange={() => {
                    formik.setFieldValue(
                      'discountAsPercentage',
                      !formik.values.discountAsPercentage
                    );
                    formik.setFieldValue('discount', 0, false);
                  }}
                  size="small"
                  sx={{
                    color: alpha('#2563EB', 0.5),
                    '&.Mui-checked': { color: '#2563EB' },
                    p: 0.5,
                  }}
                />
              }
              label={
                <Typography
                  sx={{ color: '#142352', fontSize: '0.84rem', fontWeight: 600 }}
                >
                  Apply as Percentage (%)
                </Typography>
              }
              sx={{ m: 0 }}
            />
          </Box>

          {/* Preview */}
          {formik.values.discount > 0 && (
            <Box
              sx={{
                background: alpha('#2563EB', 0.05),
                border: `1px solid ${alpha('#2563EB', 0.15)}`,
                borderRadius: '6px',
                mt: 2.5,
                px: 2,
                py: 1.5,
              }}
            >
              <Typography
                sx={{ color: alpha('#142352', 0.6), fontSize: '0.75rem', fontWeight: 600, mb: 0.3 }}
              >
                Discount Applied
              </Typography>
              <Typography
                sx={{ color: '#142352', fontSize: '1rem', fontWeight: 800 }}
              >
                {formik.values.discount}
                {formik.values.discountAsPercentage ? '%' : ' (fixed amount)'}
              </Typography>
            </Box>
          )}
        </Box>
      </DialogContent>

      {/* Footer */}
      <DialogActions sx={{ p: 0 }}>
        <Box
          sx={{
            borderTop: `1px solid ${alpha(appColors.blueGreyishLight[80], 0.12)}`,
            display: 'flex',
            gap: 1.5,
            justifyContent: 'space-between',
            px: 3,
            py: 2,
            width: '100%',
          }}
        >
          {/* Remove discount — only shown when a discount is active */}
          <Button
            disabled={!selectDis.discount}
            onClick={() => {
              dispatch(addDiscount({ discount: 0, discountAsPercentage: false }));
              handleClose();
            }}
            sx={{
              borderColor: alpha('#B42318', 0.35),
              borderRadius: '6px',
              color: '#B42318',
              fontWeight: 700,
              px: 2.5,
              whiteSpace: 'nowrap',
              '&:hover': {
                background: alpha('#B42318', 0.05),
                borderColor: '#B42318',
              },
              '&.Mui-disabled': {
                borderColor: alpha('#B42318', 0.15),
                color: alpha('#B42318', 0.3),
              },
            }}
            variant="outlined"
          >
            Remove Discount
          </Button>

          <Box sx={{ display: 'flex', gap: 1.5 }}>
          <Button
            onClick={handleClose}
            sx={{
              borderColor: alpha('#142352', 0.2),
              borderRadius: '6px',
              color: '#142352',
              fontWeight: 700,
              px: 2.5,
              '&:hover': {
                background: alpha('#142352', 0.04),
                borderColor: alpha('#142352', 0.35),
              },
            }}
            variant="outlined"
          >
            Cancel
          </Button>
          <Button
            sx={{
              background: 'linear-gradient(135deg, #2563EB 0%, #1d4ed8 100%)',
              borderRadius: '6px',
              boxShadow: `0 4px 14px ${alpha('#2563EB', 0.35)}`,
              color: appColors.white,
              fontWeight: 700,
              px: 3,
              '&:hover': {
                background: 'linear-gradient(135deg, #1d4ed8 0%, #1e40af 100%)',
                boxShadow: `0 6px 18px ${alpha('#2563EB', 0.45)}`,
              },
            }}
            type="submit"
            variant="contained"
          >
            Apply Discount
          </Button>
          </Box>
        </Box>
      </DialogActions>
    </Dialog>
  );
};

export default React.memo(DiscountModel);
